#include "KS/SRC/vector3d_shared.h"

extern "C" float sqrtf(float);
inline float length(const vector3d &v) { return sqrtf(v.x*v.x + v.y*v.y + v.z*v.z); }
inline vector3d &operator/=(vector3d &v, float d) { float r=1.0f/d; v.x*=r; v.y*=r; v.z*=r; return v; }
inline float dot(const vector3d &a, const vector3d &b) { return a.x*b.x+a.y*b.y+a.z*b.z; }

enum WaveMarkerEnum { WAVE_MarkerTubeGapStart=53, WAVE_MarkerTubeGapEnd=54 };
extern vector3d *WAVE_GetMarker(WaveMarkerEnum);

class entity {
    char pad[0x30]; vector3d position;
public: const vector3d &get_abs_position() const { return position; }
};
class board_controller {
    char pad[0xDD4]; int region;
public: int GetWaveRegion() const { return region; }
};
class ScoringManager { public: void AddGap(int); };
class game {
    char pad[0x228]; int beach;
public: int get_beach_id() const { return beach; }
};
extern game *g_game_ptr;
enum EventType { SS_TUBE_MID=32, SS_TUBE_DEEP=33 };
class SoundScriptManager {
public:
    static SoundScriptManager *instance;
    static SoundScriptManager *inst() { return instance; }
    int playEvent(EventType, entity *source=0, float fade=0.0f);
};
class kellyslater_controller {
    char pad0[0xC]; entity *owner;
    char pad1[0xDC8]; board_controller my_board_controller;
    char pad2[0x310]; ScoringManager my_scoreManager;
    char pad3[0x9A4]; bool passed_first_tube_thresh; bool passed_second_tube_thresh;
public:
    entity *get_owner() const { return owner; }
    bool Z_Within_Tube();
    void DetermineTubeGaps();
};
extern float g_tube_gap1, g_tube_gap2;

__asm__(".equ WAVE_GetMarker__F14WaveMarkerEnum,0x0037D7E8");
__asm__(".equ g_game_ptr,0x0046AC64");
__asm__(".equ _18SoundScriptManager$instance,0x0046B4A0");
__asm__(".equ Z_Within_Tube__22kellyslater_controller,0x00223978");
__asm__(".equ AddGap__14ScoringManageri,0x00247C78");
__asm__(".equ playEvent__18SoundScriptManager9EventTypeP6entityf,0x0031C380");
__asm__(".equ g_tube_gap1,0x00424C60");
__asm__(".equ g_tube_gap2,0x00424C64");

void kellyslater_controller::DetermineTubeGaps(void)
{
	int region = my_board_controller.GetWaveRegion();
	if ((region != 9) || !this->Z_Within_Tube())
	{
		passed_first_tube_thresh = false;
		passed_second_tube_thresh = false;
		return;
	}

	int current_beach = g_game_ptr->get_beach_id ();

	vector3d tube_start = *WAVE_GetMarker(WAVE_MarkerTubeGapEnd) - *WAVE_GetMarker(WAVE_MarkerTubeGapStart);
	float len = length(tube_start);
	if (len > 0.0f)
		tube_start /= len;

	vector3d tube_pos = get_owner()->get_abs_position() - *WAVE_GetMarker(WAVE_MarkerTubeGapStart);
	float perc = dot(tube_pos, tube_start);

	if ((perc > g_tube_gap2*len) && !passed_second_tube_thresh && passed_first_tube_thresh)
	{
		my_scoreManager.AddGap((current_beach * 2) + 1);
		passed_second_tube_thresh = true;
		SoundScriptManager::inst()->playEvent(SS_TUBE_DEEP);
	}

	if ((perc > g_tube_gap1*len) && !passed_first_tube_thresh)
	{
		my_scoreManager.AddGap(current_beach * 2);
		passed_first_tube_thresh = true;
		SoundScriptManager::inst()->playEvent(SS_TUBE_MID);
	}
}
